"""(267) 貯蓄の在庫に比例する流れの棚卸し表 measurements/stockflow267_20261011.tsv を作る。
手で読んだ列（在りか・式・係数・向き・走るか）と、計器つき10種の flow_s から読んだ列（ratios_r264.tsv＝an_stockflow267.py の出力）を合わせる。
使い方：python mk_table267.py <ratios_r264.tsv> > stockflow267_20261011.tsv   （PYTHONUTF8=1・改行は LF）
⚠AI の整理・推奨の列は〈AI の推奨・作者の承認は未確認〉。
"""
import csv, io, sys
sys.stdout.reconfigure(newline='\n')   # Windows の文字モードは LF を CRLF に変える＝LF のまま出す

R = {}
for r in csv.DictReader(io.open(sys.argv[1], encoding='utf-8', newline=''), delimiter='\t'):
    R[(r['nation'], r['window'], r['key'])] = (float(r['median_over_income']), float(r['min']), float(r['max']), float(r['median_over_gdp']) if r['median_over_gdp'] else float('nan'))
WINS = ['Q5〜Q40', 'Q41〜Q80', 'Q81〜Q160', 'Q161〜Q240', 'Q241〜Q400', 'Q401〜Q667']
UK, FR, NL = 'イギリス', 'フランス', 'ネーデルラント'


def v(n, w, k, nd=4):
    x = R.get((n, w, k))
    return '' if x is None else f'{x[0]:.{nd}f}'


def pipe(n, k, nd=3, gdp=False):
    out = []
    for w in WINS:
        x = R.get((n, w, k))
        out.append('' if x is None else f'{(x[3] if gdp else x[0]):.{nd}f}')
    return '|'.join(out)


def peak(k):   # 英の最大の窓（中央が最大）の 窓名・最小〜最大
    best = None
    for w in WINS:
        x = R.get((UK, w, k))
        if x and (best is None or x[0] > best[1][0]): best = (w, x)
    return '' if best is None or best[1][0] <= 0 else f'{best[0]}:{best[1][1]:.4f}〜{best[1][2]:.4f}'


H = ['番号', '区分', '名前', '在りか（ファイル:行）', '式（期間つき）', '率の係数と値（期間つき）', '流れの向き（誰から誰へ）', '既定の世界で走るか',
     'flow_s の経路名（(264) の呼び出しの位置）', '計器の鍵',
     '英 年額÷年所得 Q5〜Q40', '英 Q41〜Q80', '英 Q81〜Q160', '英 Q161〜Q240', '英 Q241〜Q400', '英 Q401〜Q667',
     '仏 年額÷年所得 6窓（Q5〜Q40|Q41〜Q80|Q81〜Q160|Q161〜Q240|Q241〜Q400|Q401〜Q667）', '蘭 年額÷年所得 6窓（同じ順）', '英 年額÷年GDP 6窓（同じ順）', '英の最大の窓の最小〜最大（10種）',
     '英 年額÷対応する在庫（Q5〜Q40）', '置き直し（英は目標 貨幣÷年GDP 0.5・投資家の取り分0.67）で縮む向きと大きさ', '段3 の前に直すか（AI の推奨・作者の承認は未確認）', '備考・限界']

rows = []


def add(id_, kind, name, where, formula, rate, direction, runs, route, key, stock_rate, shrink, rec, note):
    rows.append([id_, kind, name, where, formula, rate, direction, runs, route, key] + [v(UK, w, key) if key else '' for w in WINS]
                + [pipe(FR, key) if key else '', pipe(NL, key) if key else '', pipe(UK, key, gdp=True) if key else '', peak(key) if key else '', stock_rate, shrink, rec, note])


